import{_ as t,o as i,c as r,a1 as a}from"./chunks/framework.CiMD_7j0.js";const p=JSON.parse('{"title":"Security & Permissions","description":"","frontmatter":{"AIGC":{"ContentProducer":"001191110102MAD55U9H0F10002","ContentPropagator":"001191110102MAD55U9H0F10002","Label":"1","ProduceID":"22790660-78b1-4e56-918d-7a265941b564","PropagateID":"22790660-78b1-4e56-918d-7a265941b564","ReservedCode1":"6bf8ee81-39d1-4e64-8fe6-f9fb6cd30fa0","ReservedCode2":"6bf8ee81-39d1-4e64-8fe6-f9fb6cd30fa0"}},"headers":[],"relativePath":"en/guide/go/security.md","filePath":"en/guide/go/security.md","lastUpdated":null}'),o={name:"en/guide/go/security.md"};function s(d,e,n,l,c,u){return i(),r("div",null,[...e[0]||(e[0]=[a(`<h1 id="security-permissions" tabindex="-1">Security &amp; Permissions <a class="header-anchor" href="#security-permissions" aria-label="Permalink to &quot;Security &amp; Permissions&quot;">​</a></h1><h2 id="four-layer-permission-model" tabindex="-1">Four-Layer Permission Model <a class="header-anchor" href="#four-layer-permission-model" aria-label="Permalink to &quot;Four-Layer Permission Model&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Typical scenario</th><th>Implementation</th></tr></thead><tbody><tr><td>No login</td><td>Website home, marketplace list</td><td>Routes registered in the public group</td></tr><tr><td>Login required</td><td>Profile, my data</td><td><code>jwt_auth</code> middleware</td></tr><tr><td>Rule-based authorization</td><td>User, role, plugin management</td><td><code>permission</code> middleware + permission identifiers</td></tr><tr><td>Data scope</td><td>Access only your own data</td><td>Service layer filters by <code>user_id</code></td></tr></tbody></table><p>The frontend <code>v-permission</code> directive only hides buttons — it never replaces backend permission checks. Plugin APIs must re-check permissions and resource ownership on the server.</p><h2 id="rbac-five-table-model" tabindex="-1">RBAC Five-Table Model <a class="header-anchor" href="#rbac-five-table-model" aria-label="Permalink to &quot;RBAC Five-Table Model&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sys_user ──┬── sys_user_role ── sys_role</span></span>
<span class="line"><span>                               │</span></span>
<span class="line"><span>                            sys_role_menu ── sys_menu</span></span></code></pre></div><p>Users link menu permissions through roles; permission identifiers follow the <code>module:resource:action</code> format (e.g. <code>system:user:list</code>).</p><h2 id="dual-token-jwt" tabindex="-1">Dual-Token JWT <a class="header-anchor" href="#dual-token-jwt" aria-label="Permalink to &quot;Dual-Token JWT&quot;">​</a></h2><ul><li><strong>access token</strong>: valid 24 hours (<code>jwt.expire_minutes: 1440</code>), used for API auth.</li><li><strong>refresh token</strong>: valid 7 days (<code>jwt.refresh_expire_days: 7</code>), used to refresh access tokens.</li><li><strong>TokenVersion</strong>: incremented on password change; old tokens expire immediately.</li><li><strong>Blacklist</strong>: tokens are added to the blacklist on logout or forced revocation.</li><li><strong>Algorithm whitelist</strong>: HS256 only.</li></ul><h2 id="login-brute-force-protection" tabindex="-1">Login Brute-Force Protection <a class="header-anchor" href="#login-brute-force-protection" aria-label="Permalink to &quot;Login Brute-Force Protection&quot;">​</a></h2><p>5 consecutive failed logins lock the account for 30 minutes (<code>login_guard</code> middleware).</p><h2 id="api-rate-limit" tabindex="-1">API Rate Limit <a class="header-anchor" href="#api-rate-limit" aria-label="Permalink to &quot;API Rate Limit&quot;">​</a></h2><p>300 requests per IP per minute, burst 50. Exceeding it returns 429.</p><h2 id="upload-whitelist" tabindex="-1">Upload Whitelist <a class="header-anchor" href="#upload-whitelist" aria-label="Permalink to &quot;Upload Whitelist&quot;">​</a></h2><p>Uploaded file types and sizes are controlled by config; executables and scripts are rejected.</p><h2 id="production-key-circuit-breaker" tabindex="-1">Production Key Circuit-Breaker <a class="header-anchor" href="#production-key-circuit-breaker" aria-label="Permalink to &quot;Production Key Circuit-Breaker&quot;">​</a></h2><p>When <code>app.debug: false</code>, startup detects whether <code>jwt.secret</code> is still the default <code>change-me-in-production</code>; if so, it refuses to start.</p><h2 id="zip-security-check" tabindex="-1">ZIP Security Check <a class="header-anchor" href="#zip-security-check" aria-label="Permalink to &quot;ZIP Security Check&quot;">​</a></h2><p>L2 plugin ZIPs are checked by <code>zipguard</code>:</p><ul><li>ZIP-bomb protection: extracted size limit 200 MB, single file 50 MB.</li><li>Entry count limit: 2000.</li><li>Symbolic links and absolute path entries rejected.</li></ul>`,20)])])}const m=t(o,[["render",s]]);export{p as __pageData,m as default};
